116	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
117	// 动作文本与顺序原样保存（顺序影响相等性）。
118	type storedVoteProposal struct {
119		ID          string             `json:"id"`
120		State       string             `json:"state"`
121		Members     []storedMember     `json:"members"`
122		Delegations []storedDelegation `json:"delegations"`
123		Quorum      int64              `json:"quorum"`
124		StartAt     int64              `json:"start_at"`
125		Deadline    int64              `json:"deadline"`
126		TimelockEnd int64              `json:"timelock_end"`
127		Actions     []string           `json:"actions"`
128		Ballots     []storedBallot     `json:"ballots"`
129		Tally       *storedTally       `json:"tally,omitempty"`
130	}
131	
132	// ---- 校验与派生 ----
133	
134	type proposalSpec struct {
135		members  []VoteMember
136		weights  map[string]int64
137		delegate map[string]string // 直接委托对象
138		pathOf   map[string][]string
139		headOf   map[string]string // 最终代表
140		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
141		total    int64
142	}
143	
144	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
145	// 任何非法条件都返回错误，调用方必须整项拒绝。
146	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
147		if in.ID == "" {
148			return nil, invalidProposal("proposal id must not be empty")
149		}
150		if len(in.Members) == 0 {
151			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
152		}
153		weights := make(map[string]int64, len(in.Members))
154		order := make([]string, 0, len(in.Members))
155		for _, m := range in.Members {
156			if m.ID == "" {
157				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
158			}
159			if _, dup := weights[m.ID]; dup {
160				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
161			}
162			if m.Weight <= 0 {
163				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
164			}
165			weights[m.ID] = m.Weight
166			order = append(order, m.ID)
167		}
168	
169		// 总权重必须在 int64 范围内（各权重已为正）。
170		var total int64
171		for _, m := range in.Members {
172			sum, ok := addInt64(total, m.Weight)
173			if !ok {
174				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
175			}
176			total = sum
177		}
178	
179		if in.Quorum < 1 || in.Quorum > total {
180			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
181		}
182		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
183			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
184				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
185		}
186	
187		delegate := make(map[string]string, len(in.Delegations))
188		for _, d := range in.Delegations {
189			if d.From == "" || d.To == "" {
190				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
191			}
192			if _, ok := weights[d.From]; !ok {
193				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
194			}
195			if _, ok := weights[d.To]; !ok {
196				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
197			}
198			if d.From == d.To {
199				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
200			}
201			if _, dup := delegate[d.From]; dup {
202				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
203			}
204			delegate[d.From] = d.To
205		}
206	
207		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
208		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
209		// 所以该遍历必然终止。
210		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
211		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
212		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
213		pathOf := make(map[string][]string, len(weights))
214		headOf := make(map[string]string, len(weights))
215		for _, id := range order {
216			if _, done := headOf[id]; done {
217				continue
218			}
219			chain := []string{id}
220			onChain := map[string]int{id: 0}
221			cur := id
222			for {
223				next, has := delegate[cur]
224				if !has {
225					break // cur 即未再委托的最终代表
226				}
227				if pos, cyc := onChain[next]; cyc {
228					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
229				}
230				if resolved, ok := pathOf[next]; ok {
231					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
232					chain = append(chain, resolved...)
233					cur = resolved[len(resolved)-1]
234					break
235				}
236				chain = append(chain, next)
237				onChain[next] = len(chain) - 1
238				cur = next
239			}
240			head := cur
241			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
242			// 后缀成员均已登记，这里只补齐尚未解析的成员。
243			for i := 0; i < len(chain); i++ {
244				member := chain[i]
245				if _, ok := headOf[member]; !ok {
246					pathOf[member] = append([]string(nil), chain[i:]...)
247					headOf[member] = head
248				}
249			}
250		}
251	
252		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
253		groupW := make(map[string]int64)
254		for _, id := range order {
255			head := headOf[id]
256			sum, ok := addInt64(groupW[head], weights[id])
257			if !ok {
258				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
259			}
260			groupW[head] = sum
261		}
262	
263		return &proposalSpec{
264			members:  append([]VoteMember(nil), in.Members...),
265			weights:  weights,
266			delegate: delegate,
267			pathOf:   pathOf,
268			headOf:   headOf,
269			groupW:   groupW,
270			total:    total,
271		}, nil
272	}
273	
274	func invalidProposal(format string, args ...any) error {
275		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
276	}
277	
278	// proposalsEqual 判断重试内容是否与已存提案逐项相同。
279	// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
280	func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
281		if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
282			stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
283			return false
284		}
285		if !sameActions(stored.Actions, in.Actions) {
286			return false
287		}
288		if len(stored.Members) != len(in.Members) {
289			return false
290		}
291		for _, m := range stored.Members {
292			if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
293				return false
294			}
295		}
296		if len(stored.Delegations) != len(in.Delegations) {
297			return false
298		}
299		for _, d := range stored.Delegations {
300			to, ok := spec.delegate[d.From]
301			if !ok || to != d.To {
302				return false
303			}
304		}
305		return true
306	}
307	
308	// ---- 存储操作 ----
309	
310	// CreateVoteProposal 创建一项投票提案。
311	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
312	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
313	// 非法条件整项拒绝，不落盘任何部分变化。
314	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
315		spec, err := validateProposalInput(in)
316		if err != nil {
317			return nil, false, err
318		}
319		commit, err := s.begin()
320		if err != nil {
321			return nil, false, err
322		}
323		defer commit()
324	
325		state, err := s.loadLocked()
326		if err != nil {
327			return nil, false, err
328		}
329		if existing, ok := state.VoteProposals[in.ID]; ok {
330			if !proposalsEqual(existing, in, spec) {
331				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
332			}
333			v := voteProposalView(existing)
334			return v, true, nil
335		}
336		if _, ok := state.Proposals[in.ID]; ok {
337			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
338			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
339		}
340	
341		stored := &storedVoteProposal{
342			ID:          in.ID,
343			State:       "voting",
344			Members:     make([]storedMember, 0, len(in.Members)),
345			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
346			Quorum:      in.Quorum,
347			StartAt:     in.StartAt,
348			Deadline:    in.Deadline,
349			TimelockEnd: in.TimelockEnd,
350			Actions:     copyActions(in.Actions),
351			Ballots:     []storedBallot{},
352		}
353		for _, m := range in.Members {
354			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
355		}
356		for _, d := range in.Delegations {
357			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
358		}
359		state.VoteProposals[in.ID] = stored
360		if err := s.commitLocked(state); err != nil {
361			return nil, false, err
362		}
363		return voteProposalView(stored), false, nil
364	}
365	
366	func voteReject(reason string) error {
367		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
368	}
369	
370	func tallyReject(reason string) error {
371		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
372	}
373	
374	// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----
375	
376	// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
377	// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
378	// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
379	type ballotCounts struct {
380		forWeight     int64
381		againstWeight int64
382	}
383	
384	// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
385	// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
386	// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
387	func (c ballotCounts) turnout() (int64, bool) {
388		return addInt64(c.forWeight, c.againstWeight)
389	}
390	
391	// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
392	// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
393	// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
394	// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
395	func votePasses(forWeight, againstWeight, quorum int64) bool {
396		if forWeight <= againstWeight {
397			return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
398		}
399		return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
400	}
401	
402	// tallyVerdict 把通过条件映射为提案首次计票后的状态。
403	func tallyVerdict(passed bool) string {
404		if passed {
405			return "passed"
406		}
407		return "rejected"
408	}
409	
410	// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
411	// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
412	func countBallots(ballots []storedBallot) (ballotCounts, error) {
413		var c ballotCounts
414		for _, b := range ballots {
415			if b.Support {
416				sum, ok := addInt64(c.forWeight, b.Weight)
417				if !ok {
418					return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
419				}
420				c.forWeight = sum
421			} else {
422				sum, ok := addInt64(c.againstWeight, b.Weight)
423				if !ok {
424					return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
425				}
426				c.againstWeight = sum
427			}
428		}
429		return c, nil
430	}
431	
432	// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
433	// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
434	// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
435	// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
436	// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
437	// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
438	func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
439		seen := map[string]bool{}
440		for i, b := range ballots {
441			if b.Representative == "" {
442				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
443			}
444			if spec.headOf[b.Representative] != b.Representative {
445				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
446					id, i, b.Representative)
447			}
448			if seen[b.Representative] {
449				return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
450			}
451			seen[b.Representative] = true
452			if b.Weight != spec.groupW[b.Representative] {
453				return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
454					id, b.Representative, b.Weight, spec.groupW[b.Representative])
455			}
456		}
457		counts, err := countBallots(ballots)
458		if err != nil {
459			return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
460		}
461		return counts, nil
462	}
463	
464	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
465	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
466	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
467	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
468	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
469		if voter == "" {
470			return nil, voteReject("voter id must not be empty")
471		}
472		commit, err := s.begin()
473		if err != nil {
474			return nil, err
475		}
476		defer commit()
477	
478		state, err := s.loadLocked()
479		if err != nil {
480			return nil, err
481		}
482		p, ok := state.VoteProposals[id]
483		if !ok {
484			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
485		}
486		spec, verr := specOf(p)
487		if verr != nil {
488			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
489		}
490		if _, member := spec.weights[voter]; !member {
491			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
492		}
493		if spec.headOf[voter] != voter {
494			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
495		}
496		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
497		// 改投另一选择报冲突，绝不静默覆盖。
498		for i := range p.Ballots {
499			if p.Ballots[i].Representative == voter {
500				if p.Ballots[i].Support != support {
501					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
502						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
503				}
504				b := p.Ballots[i]
505				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
506			}
507		}
508		if p.Tally != nil {
509			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
510		}
511		if now < p.StartAt || now >= p.Deadline {
512			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
513		}
514	
515		p.Ballots = append(p.Ballots, storedBallot{
516			Representative: voter,
517			Weight:         spec.groupW[voter],
518			Support:        support,
519			VotedAt:        now,
520		})
521		if err := s.commitLocked(state); err != nil {
522			return nil, err
523		}
524		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
525	}
526	
527	func voteChoice(support bool) string {
528		if support {
529			return "for"
530		}
531		return "against"
532	}
533	
534	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
535	// 且赞成严格多于反对才通过。未投权重不计入参与量。
536	// 计票只确定状态，不转账；再次计票始终返回首次结论。
537	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
538		commit, err := s.begin()
539		if err != nil {
540			return nil, err
541		}
542		defer commit()
543	
544		state, err := s.loadLocked()
545		if err != nil {
546			return nil, err
547		}
548		p, ok := state.VoteProposals[id]
549		if !ok {
550			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
551		}
552		if p.Tally != nil {
553			return storedTallyResult(p), nil
554		}
555		if now < p.Deadline {
556			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
557		}
558	
559		spec, verr := specOf(p)
560		if verr != nil {
561			return nil, verr
562		}
563		// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
564		// 同时用于首次计票、打开文件时的重放校验与查询结论。
565		counts, verr := verifyBallots(id, p.Ballots, spec)
566		if verr != nil {
567			return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
568		}
569		passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
570		p.Tally = &storedTally{ForWeight: counts.forWeight, AgainstWeight: counts.againstWeight, TalliedAt: now}
571		p.State = tallyVerdict(passed)
572		if err := s.commitLocked(state); err != nil {
573			return nil, err
574		}
575		return storedTallyResult(p), nil
576	}
577	
578	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
579	// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
580	// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
581	// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
582	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
583		if p.Tally == nil {
584			return nil
585		}
586		c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
587		turnout, _ := c.turnout()
588		return &TallyResultView{
589			ForWeight:     c.forWeight,
590			AgainstWeight: c.againstWeight,
591			Turnout:       turnout,
592			Quorum:        p.Quorum,
593			Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
594			TalliedAt:     p.Tally.TalliedAt,
595		}
596	}
597	
598	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
599	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
600		state, err := s.readState()
601		if err != nil {
602			return nil, false, err
603		}
604		p, ok := state.VoteProposals[id]
605		if !ok {
606			return nil, false, nil
607		}
608		return voteProposalView(p), true, nil
609	}
610	
611	// VoteProposals 返回全部投票提案，按编号排序。
612	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
613		state, err := s.readState()
614		if err != nil {
615			return nil, err
616		}
617		return voteProposalViews(state), nil
618	}
619	
620	func voteProposalViews(state *storedState) []*VoteProposalView {
621		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
622		for _, p := range state.VoteProposals {
623			out = append(out, voteProposalView(p))
624		}
625		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
626		return out
627	}
628	
629	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
630		spec, err := specOf(p)
631		if err != nil {
632			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
633			panic("govflow: building view of corrupt proposal: " + err.Error())
634		}
635		members := make([]MemberView, 0, len(p.Members))
636		for _, m := range p.Members { // 保持成员提交顺序
637			mv := MemberView{
638				ID:       m.ID,
639				Weight:   m.Weight,
640				Path:     append([]string(nil), spec.pathOf[m.ID]...),
641				Delegate: spec.headOf[m.ID],
642			}
643			if to, ok := spec.delegate[m.ID]; ok {
644				mv.Direct = to
645			}
646			members = append(members, mv)
647		}
648		ballots := make([]BallotView, 0, len(p.Ballots))
649		for _, b := range p.Ballots { // 保持首次投票先后顺序
650			ballots = append(ballots, BallotView{
651				Representative: b.Representative,
652				Weight:         b.Weight,
653				Support:        b.Support,
654				VotedAt:        b.VotedAt,
655			})
656		}
657		v := &VoteProposalView{
658			ID:          p.ID,
659			Source:      "vote",
660			State:       p.State,
661			Quorum:      p.Quorum,
662			StartAt:     p.StartAt,
663			Deadline:    p.Deadline,
664			TimelockEnd: p.TimelockEnd,
665			Actions:     copyActions(p.Actions),
666			TotalWeight: spec.total,
667			Members:     members,
668			Ballots:     ballots,
669		}
670		if p.Tally != nil {
671			v.Tally = storedTallyResult(p)
672		}
673		return v
674	}
675	
676	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
677	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
678		in := &CreateVoteInput{
679			ID:          p.ID,
680			Quorum:      p.Quorum,
681			StartAt:     p.StartAt,
682			Deadline:    p.Deadline,
683			TimelockEnd: p.TimelockEnd,
684			Actions:     p.Actions,
685		}
686		in.Members = make([]VoteMember, len(p.Members))
687		for i, m := range p.Members {
688			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
689		}
690		in.Delegations = make([]Delegation, len(p.Delegations))
691		for i, d := range p.Delegations {
692			in.Delegations[i] = Delegation{From: d.From, To: d.To}
693		}
694		return validateProposalInput(in)
695	}
696	
697	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
698	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
699	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
700	func validateVoteProposals(state *storedState) error {
701		for key, p := range state.VoteProposals {
702			if p == nil {
703				return fmt.Errorf("voting proposal %q is empty", key)
704			}
705			if p.ID != key || p.ID == "" {
706				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
707			}
708			if _, collide := state.Proposals[p.ID]; collide {
709				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
710			}
711			switch p.State {
712			case "voting", "passed", "rejected", "executed":
713			default:
714				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
715			}
716			spec, err := specOf(p)
717			if err != nil {
718				return err
719			}
720	
721			// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
722			// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
723			// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
724			counts, err := verifyBallots(p.ID, p.Ballots, spec)
725			if err != nil {
726				return err
727			}
728			// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
729			// 仍只属于打开时的明细校验。
730			for _, b := range p.Ballots {
731				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
732					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
733						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
734				}
735			}
736	
737			switch {
738			case p.Tally == nil:
739				if p.State != "voting" {
740					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
741				}
742			default:
743				if p.State == "voting" {
744					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
745				}
746				if p.Tally.TalliedAt < p.Deadline {
747					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
748				}
749				if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
750					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
751						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
752				}
753				// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
754				// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
755				passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
756				if passedNow != (p.State == "passed" || p.State == "executed") {
757					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
758				}
759			}
760		}
761		return nil
762	}
