508		// 一次快照读取保证登记提案与投票提案来自同一份已提交状态，
509		// 不会把并发执行前后的提案状态拼在一起。
510		snapshot, err := store.ProposalsSnapshot()
511		if err != nil {
512			fail(err)
513		}
514		registered := snapshot.Registered
515		voting := snapshot.Voting
516		if cf.asJSON {
517			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
518			merged := make([]any, 0, len(registered)+len(voting))
519			for _, r := range registered {
520				merged = append(merged, r)
521			}
522			for _, v := range voting {
523				merged = append(merged, v)
524			}
525			emitJSON(merged)
526			return
527		}
528		for _, record := range registered {
529			printProposalText(record)
530		}
531		for _, view := range voting {
532			printVoteProposalText(view)
533		}
534	}
