// scanFrame 是结构扫描的栈帧。
type scanFrame struct {
	node    *schemaNode
	isArray bool
	opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
	seen    map[string]bool
	atValue bool // 对象帧：下一个待消费 token 是值而非键
	index   int  // 数组帧：下一个元素下标
	path    string
}

// checkStateStructure 在解码前逐 token 扫描状态文件：
//   - 同一对象内键（按 JSON 解读后的字符串）不得重复；
//   - 固定字段对象的键必须与保存格式的字段名逐字一致，大小写变体同样拒绝；
//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，不做字段名检查。
//
// 报错会带上出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]）。
func checkStateStructure(raw []byte) error {
